<?php
require_once __DIR__ . '/../../includes/auth-check.php';
require_once __DIR__ . '/../../includes/admin-ui.php';
require_once __DIR__ . '/../../includes/analytics.php';
require_once __DIR__ . '/../../includes/cache.php';
admin_require_permission($pdo,$admin,'manage_pages');
$id=filter_var(request_string($_GET, 'id', request_string($_POST, 'id')), FILTER_VALIDATE_INT)?:0;
$page=['id'=>0,'slug'=>'','legacy_file'=>null,'title'=>'','excerpt'=>'','content_html'=>'','seo_title'=>'','seo_description'=>'','canonical_url'=>'','og_image'=>'','status'=>'draft','noindex'=>0];
if($id){$get=$pdo->prepare('SELECT * FROM site_pages WHERE id=:id');$get->execute(['id'=>$id]);$page=$get->fetch()?:null;if(!$page){http_response_code(404);exit('Page not found.');}}
$errorMessage='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$title=trim(substr(strip_tags(request_string($_POST, 'title', '')),0,255));$slug=slugify((string)($_POST['slug']??$title));$excerpt=trim(substr(strip_tags(request_string($_POST, 'excerpt', '')),0,500));$content=sanitize_rich_html(request_string($_POST, 'content_html', ''));$seoTitle=trim(substr(strip_tags(request_string($_POST, 'seo_title', '')),0,255));$seoDescription=trim(substr(strip_tags(request_string($_POST, 'seo_description', '')),0,320));$canonical=trim(substr(request_string($_POST, 'canonical_url', ''),0,500));$ogImage=trim(substr(request_string($_POST, 'og_image', ''),0,500));$status=in_array(($_POST['status']??''),['draft','published','archived'],true)?(string)$_POST['status']:'draft';$noindex=isset($_POST['noindex'])?1:0;
 if($title===''||$slug===''||$content==='')$errorMessage='Title, a valid URL slug and page content are required.';
 if(($page['slug']??'')==='contact'&&$slug!=='contact')$errorMessage='The built-in contact page slug is reserved for the working contact form.';
 if($canonical!==''&&!(str_starts_with($canonical,'/')&&!str_starts_with($canonical,'//'))&&(!filter_var($canonical,FILTER_VALIDATE_URL)||!in_array(strtolower((string)parse_url($canonical,PHP_URL_SCHEME)),['http','https'],true)))$errorMessage='Canonical URL must be a local path or valid HTTP/HTTPS URL.';
 if($ogImage!==''&&!(str_starts_with($ogImage,'/')&&!str_starts_with($ogImage,'//'))&&(!filter_var($ogImage,FILTER_VALIDATE_URL)||strtolower((string)parse_url($ogImage,PHP_URL_SCHEME))!=='https'))$errorMessage='OpenGraph image must be a local path or HTTPS URL.';
 $duplicate=$pdo->prepare('SELECT id FROM site_pages WHERE slug=:slug AND id<>:id LIMIT 1');$duplicate->execute(['slug'=>$slug,'id'=>$id]);if($duplicate->fetchColumn())$errorMessage='That page slug is already used.';
 if($errorMessage===''){
  try{
   $upload=save_uploaded_image('og_image_file','uploads/pages');if($upload!==null)$ogImage=$upload;
   $values=['slug'=>$slug,'title'=>$title,'excerpt'=>$excerpt,'content'=>$content,'seo_title'=>$seoTitle,'seo_description'=>$seoDescription,'canonical'=>$canonical,'og_image'=>$ogImage,'status'=>$status,'noindex'=>$noindex,'updated_by'=>(int)$admin['id']];
   if($id){$values['id']=$id;$save=$pdo->prepare('UPDATE site_pages SET slug=:slug,title=:title,excerpt=:excerpt,content_html=:content,seo_title=:seo_title,seo_description=:seo_description,canonical_url=:canonical,og_image=:og_image,status=:status,noindex=:noindex,updated_by=:updated_by WHERE id=:id');$save->execute($values);}
   else{$values['created_by']=(int)$admin['id'];$save=$pdo->prepare('INSERT INTO site_pages(slug,title,excerpt,content_html,seo_title,seo_description,canonical_url,og_image,status,noindex,created_by,updated_by) VALUES(:slug,:title,:excerpt,:content,:seo_title,:seo_description,:canonical,:og_image,:status,:noindex,:created_by,:updated_by)');$save->execute($values);$id=(int)$pdo->lastInsertId();}
   audit_log($pdo,(int)$admin['id'],$page['id']?'page.updated':'page.created','site_page',(string)$id,'Page saved.');cache_clear_all();flash('success','Page saved.');redirect_to('admin/pages/edit?id='.$id);
  }catch(Throwable $error){error_log('Page save: '.$error->getMessage());$errorMessage='Page could not be saved. Check the URL slug and any uploaded image.';}
 }
 $page=array_merge($page,['title'=>$title,'slug'=>$slug,'excerpt'=>$excerpt,'content_html'=>$content,'seo_title'=>$seoTitle,'seo_description'=>$seoDescription,'canonical_url'=>$canonical,'og_image'=>$ogImage,'status'=>$status,'noindex'=>$noindex]);
}
admin_header($pdo,$admin,$id?'Edit page':'New page');
?>
<?php if($errorMessage!==''):?><div class="notice notice-error" role="alert"><?=e($errorMessage)?></div><?php endif;?>
<form class="admin-form" method="post" enctype="multipart/form-data" action="<?=e(app_url('admin/pages/edit'.($id?'?id='.$id:'')))?>"><?=csrf_field()?><?php if($id):?><input type="hidden" name="id" value="<?=(int)$id?>"><?php endif;?>
<section class="admin-card"><h2>Page content</h2><div class="form-row"><div class="field"><label for="title">Title</label><input id="title" name="title" maxlength="255" required value="<?=e($page['title'])?>"></div><div class="field"><label for="slug">URL slug</label><input id="slug" name="slug" maxlength="180" pattern="[a-z0-9]+(-[a-z0-9]+)*" required value="<?=e($page['slug'])?>"><small>Public URL: /pages/<?=e($page['slug']?:'your-page')?></small></div></div><div class="field"><label for="excerpt">Short summary</label><textarea id="excerpt" name="excerpt" maxlength="500" rows="3"><?=e($page['excerpt'])?></textarea></div><div class="field"><label for="content_html">Page body (sanitized rich HTML)</label><textarea class="code-input" id="content_html" name="content_html" rows="18" required><?=e($page['content_html'])?></textarea><small>Use semantic HTML such as h1, h2, p, lists and links. Script, iframe, event-handler and unsafe URL markup is removed.</small></div></section>
<section class="admin-card"><h2>SEO &amp; publication</h2><div class="form-row"><div class="field"><label for="status">Status</label><select id="status" name="status"><?php foreach(['draft','published','archived'] as $option):?><option value="<?=e($option)?>" <?=$page['status']===$option?'selected':''?>><?=e(ucfirst($option))?></option><?php endforeach;?></select></div><div class="field"><label for="canonical_url">Canonical URL (optional)</label><input id="canonical_url" name="canonical_url" maxlength="500" value="<?=e($page['canonical_url'])?>"></div></div><label class="inline-check"><input type="checkbox" name="noindex" value="1" <?=$page['noindex']?'checked':''?>><span>Set noindex, nofollow and omit from sitemap</span></label><div class="form-row"><div class="field"><label for="seo_title">SEO title</label><input id="seo_title" name="seo_title" maxlength="255" value="<?=e($page['seo_title'])?>"></div><div class="field"><label for="seo_description">SEO description</label><textarea id="seo_description" name="seo_description" maxlength="320" rows="3"><?=e($page['seo_description'])?></textarea></div></div><div class="form-row"><div class="field"><label for="og_image_file">Upload OpenGraph image (JPEG, PNG or WebP · max 5 MB)</label><input id="og_image_file" type="file" name="og_image_file" accept="image/jpeg,image/png,image/webp"></div><div class="field"><label for="og_image">OpenGraph image URL (optional)</label><input id="og_image" name="og_image" maxlength="500" value="<?=e($page['og_image'])?>"></div></div></section><div class="admin-actions"><button class="button button-primary" type="submit">Save page</button><a class="button button-small" href="<?=e(app_url('admin/pages'))?>">Back to pages</a></div></form>
<?php admin_footer(); ?>
